class Solution {
public:
    int minimizeSum(vector<int>& nums) {
        int s1 = INT_MAX, s2 = INT_MAX, s3 = INT_MAX;
        int l1 = INT_MIN, l2 = INT_MIN, l3 = INT_MIN;
        for (int x : nums) {
            // maintain three smallest: s1 <= s2 <= s3
            if (x < s1) {
                s3 = s2; s2 = s1; s1 = x;
            } else if (x < s2) {
                s3 = s2; s2 = x;
            } else if (x < s3) {
                s3 = x;
            }
            // maintain three largest: l3 <= l2 <= l1
            if (x > l1) {
                l3 = l2; l2 = l1; l1 = x;
            } else if (x > l2) {
                l3 = l2; l2 = x;
            } else if (x > l3) {
                l3 = x;
            }
        }
        // Option 1: change two smallest -> range = max - third smallest
        int opt1 = l1 - s3;
        // Option 2: change two largest -> range = third largest - min
        int opt2 = l3 - s1;
        // Option 3: change one smallest and one largest -> range = second largest - second smallest
        int opt3 = l2 - s2;
        return min({opt1, opt2, opt3});
    }
};
